import React, { useState } from 'react';
import axios from 'axios';

function App() {
  const [view, setView] = useState('login');
  const [form, setForm] = useState({
    email: '', password: '', full_name: '', telegram_chat_id: ''
  });
  const [token, setToken] = useState('');
  const [otp, setOtp] = useState('');
  const [message, setMessage] = useState('');

  const onChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const register = async () => {
    setMessage('');
    try {
      await axios.post('/api/v1/auth/register', form);
      setMessage('Registro exitoso. Ahora inicia sesión.');
      setView('login');
    } catch (e) { setMessage(e.response?.data?.detail || 'Error en registro'); }
  };

  const login = async () => {
    setMessage('');
    try {
      const { data } = await axios.post('/api/v1/auth/login', { email: form.email, password: form.password });
      setToken(data.token);
      setView('otp');
    } catch (e) { setMessage(e.response?.data?.detail || 'Error de login'); }
  };

  const requestOtp = async () => {
    setMessage('');
    try {
      await axios.post(`/api/v1/auth/request-otp?token=${encodeURIComponent(token)}`);
      setMessage('OTP enviado por Telegram. Revísalo.');
    } catch (e) { setMessage(e.response?.data?.detail || 'No se pudo enviar OTP'); }
  };

  const confirmOtp = async () => {
    setMessage('');
    try {
      // Para la demo de backend, confirm-otp acepta token y otp_code via query/body simplificado
      const res = await axios.post(`/api/v1/auth/confirm-otp?token=${encodeURIComponent(token)}&otp_code=${encodeURIComponent(otp)}`);
      if (res.data?.success) {
        setView('dashboard');
      } else {
        setMessage('OTP inválido');
      }
    } catch (e) { setMessage(e.response?.data?.detail || 'OTP inválido o expirado'); }
  };

  return (
    <div style={{ maxWidth: 480, margin: '40px auto', fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto' }}>
      <h1>LoRaGuard</h1>
      {message && <div style={{ padding: 10, background: '#eef', marginBottom: 12 }}>{message}</div>}

      {view === 'register' && (
        <div>
          <h2>Registro</h2>
          <input name="full_name" placeholder="Nombre completo" value={form.full_name} onChange={onChange} style={{ width: '100%', marginBottom: 8 }} />
          <input name="email" placeholder="Correo electrónico" value={form.email} onChange={onChange} style={{ width: '100%', marginBottom: 8 }} />
          <input type="password" name="password" placeholder="Contraseña" value={form.password} onChange={onChange} style={{ width: '100%', marginBottom: 8 }} />
          <input name="telegram_chat_id" placeholder="Telegram Chat ID" value={form.telegram_chat_id} onChange={onChange} style={{ width: '100%', marginBottom: 8 }} />
          <button onClick={register}>Registrarse</button>
          <div style={{ marginTop: 8 }}>
            ¿Ya tienes cuenta? <button onClick={() => setView('login')}>Inicia sesión</button>
          </div>
        </div>
      )}

      {view === 'login' && (
        <div>
          <h2>Login</h2>
          <input name="email" placeholder="Correo electrónico" value={form.email} onChange={onChange} style={{ width: '100%', marginBottom: 8 }} />
          <input type="password" name="password" placeholder="Contraseña" value={form.password} onChange={onChange} style={{ width: '100%', marginBottom: 8 }} />
          <button onClick={login}>Entrar</button>
          <div style={{ marginTop: 8 }}>
            ¿No tienes cuenta? <button onClick={() => setView('register')}>Regístrate</button>
          </div>
        </div>
      )}

      {view === 'otp' && (
        <div>
          <h2>Verificación OTP</h2>
          <button onClick={requestOtp} style={{ marginBottom: 8 }}>Enviar OTP a Telegram</button>
          <input placeholder="Código OTP" value={otp} onChange={(e)=>setOtp(e.target.value)} style={{ width: '100%', marginBottom: 8 }} />
          <button onClick={confirmOtp}>Confirmar</button>
        </div>
      )}

      {view === 'dashboard' && (
        <div>
          <h2>Dashboard</h2>
          <p>Acceso concedido. Aquí listaríamos archivos sensibles desencriptados bajo demanda.</p>
        </div>
      )}
    </div>
  );
}

export default App;
